"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[516],{2197(e,o,n){n.r(o),n.d(o,{assets:()=>l,contentTitle:()=>r,default:()=>h,frontMatter:()=>s,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"operation","title":"VIII. OPERATIONS POLICIES","description":"HOURS OF OPERATION","source":"@site/docs/08-operation.md","sourceDirName":".","slug":"/operation","permalink":"/pps-erp-sdd/operation","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/08-operation.md","tags":[],"version":"current","sidebarPosition":8,"frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"VII. SAFETY & WORK AREA POLICY","permalink":"/pps-erp-sdd/safety"},"next":{"title":"IX. EMPLOYEE BENEFITS AND SERVICES","permalink":"/pps-erp-sdd/benefits"}}');var t=n(4848),a=n(8453);const s={},r="VIII. OPERATIONS POLICIES",l={},d=[{value:"HOURS OF OPERATION",id:"hours-of-operation",level:2},{value:"MEETING GUIDELINES",id:"meeting-guidelines",level:3},{value:"TIME SHEETS",id:"time-sheets",level:2},{value:"PAY DAY",id:"pay-day",level:2},{value:"WAGES AND SALARIES",id:"wages-and-salaries",level:2},{value:"JOB PERFORMANCE EVALUATION",id:"job-performance-evaluation",level:2},{value:"ADVANCEMENT AND PROMOTION",id:"advancement-and-promotion",level:2},{value:"EMPLOYMENT OF RELATIVES",id:"employment-of-relatives",level:2},{value:"NON-FRATERNIZATION",id:"non-fraternization",level:2},{value:"APPEARANCE",id:"appearance",level:2},{value:"PERSONAL PHONE CALLS AND PERSONAL BUSINESS",id:"personal-phone-calls-and-personal-business",level:2},{value:"USE OF COMMUNICATION SYSTEMS",id:"use-of-communication-systems",level:2},{value:"Internet Use",id:"internet-use",level:2},{value:"Email Usage",id:"email-usage",level:2},{value:"Memory Stick (USB Key)",id:"memory-stick-usb-key",level:3},{value:"PROPRIETARY AND CONFIDENTIAL INFORMATION",id:"proprietary-and-confidential-information",level:2},{value:"COMPANY PROPERTY",id:"company-property",level:2},{value:"SMOKING",id:"smoking",level:2},{value:"LAYOFF DUE TO LACK OF WORK",id:"layoff-due-to-lack-of-work",level:2},{value:"TRAVEL",id:"travel",level:2}];function c(e){const o={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",ul:"ul",...(0,a.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(o.header,{children:(0,t.jsx)(o.h1,{id:"viii-operations-policies",children:"VIII. OPERATIONS POLICIES"})}),"\n",(0,t.jsx)(o.h2,{id:"hours-of-operation",children:"HOURS OF OPERATION"}),"\n",(0,t.jsx)(o.p,{children:"We at Pressure Profile Systems have a job to do and we rate people on the results they  achieve as well as their performance against goals. There is a need to service both internal and external customers and ensure you are available to both as well as the need to  accommodate individual work styles. Please work with management on creating an  appropriate schedule where you take the needed breaks and lunch, yet keeps you in  contact with your teammates."}),"\n",(0,t.jsx)(o.h3,{id:"meeting-guidelines",children:"MEETING GUIDELINES"}),"\n",(0,t.jsx)(o.p,{children:"To ensure meetings are conducted efficiently and effectively, the following guidelines shall be followed."}),"\n",(0,t.jsxs)(o.ul,{children:["\n",(0,t.jsx)(o.li,{children:"Meeting organizer shall use Google calendar to send out meeting notice - Meeting organizer shall use \u2019Check guest and resource availability\u2019 feature to  ensure all attendees and conference room are available"}),"\n",(0,t.jsx)(o.li,{children:"Meeting organizer shall make appropriate check marks on meeting notice to allow  guests to modify event, to invite others and to see guest list"}),"\n",(0,t.jsx)(o.li,{children:"Meeting notice shall briefly describe the purpose of the meeting"}),"\n",(0,t.jsx)(o.li,{children:"Meeting organizer shall attach meeting agenda to meeting notice or send it out at  least one day prior to the meeting"}),"\n",(0,t.jsx)(o.li,{children:"Meeting agenda shall list major discussion topics and allotted time - Attendees shall respond to the invitation as soon as possible. If you cannot attend  the meeting, please state reason."}),"\n",(0,t.jsx)(o.li,{children:"For weekly meeting, attendees shall send out notice, preferably 24 hours in  advance, to meeting organizer if you cannot attend a particular meeting - Attendees shall prepare notes, graphs, data, etc. prior to the meeting and place  them in a folder designated for this meeting"}),"\n",(0,t.jsx)(o.li,{children:"Meeting organizer shall show up at the meeting 5-10 minutes early to ensure  meeting or presentation materials are ready"}),"\n",(0,t.jsx)(o.li,{children:"All attendees shall show up at meetings on time, preferably 2-5 minutes before  start time."}),"\n",(0,t.jsx)(o.li,{children:"Meeting shall start promptly"}),"\n",(0,t.jsx)(o.li,{children:"Meeting organizer shall monitor the meeting to ensure that discussion topics and  time closely follow the agenda"}),"\n",(0,t.jsx)(o.li,{children:"Meeting shall end timely"}),"\n"]}),"\n",(0,t.jsx)(o.h2,{id:"time-sheets",children:"TIME SHEETS"}),"\n",(0,t.jsx)(o.p,{children:"Each employee is responsible for keeping a detailed Time Sheet and or Google Calendar.  The Time Sheet or Google Calendar is used for payroll and billing records which must be  maintained accurately at all times. Each employee must submit time sheets electronically  via email unless directed otherwise. Any discrepancies should be resolved with the  department manager before transmittal to the Payroll Specialist for payment."}),"\n",(0,t.jsx)(o.p,{children:"If you cannot be at work due to sickness, jury duty, or other excusable circumstance,  please notify your supervisor in advance. If you will be late in arriving at your job, notify  your supervisor personally. In the event of a disabling sickness or accident while  performing your duties, notify your supervisor immediately. If you are a non-exempt  employee, your supervisor will see that your time out is noted on your time sheet."}),"\n",(0,t.jsx)(o.h2,{id:"pay-day",children:"PAY DAY"}),"\n",(0,t.jsx)(o.p,{children:"All employees will be paid on the 10th and 25th day of the month. For paydays falling on  a Saturday, Sunday or holiday, you will then be paid the preceding Friday. If you are  absent on pay day and someone else is to pick up your check, it will not be released  without a signed, handwritten note from you authorizing the named person to pick it up.  The person designated to pick up your check will be asked to produce identification  satisfactory to management; otherwise, your check will not be released. Any deviations  from this procedure must have prior approval of an officer of the Company."}),"\n",(0,t.jsx)(o.p,{children:"Vacation pay will be paid on the regular pay cycle. If you resign with at least 72 hours  notice, you will be paid on the date of separation for all wages and accrued unused  vacation at the date of separation. If you resign with less than 72 hours notice, you will  be paid for all wages and accrued unused vacation no later than 72 hours after notice is  given. If you are terminated, you will be paid on the date of termination for all wages and  accrued unused vacation at the date of termination."}),"\n",(0,t.jsx)(o.h2,{id:"wages-and-salaries",children:"WAGES AND SALARIES"}),"\n",(0,t.jsx)(o.p,{children:"Wage rates and salaries vary according to your qualifications and previous work  experiences, and a successful, stable work record. Rates for one particular job or  classification cannot be compared as being relative to any other. Any wage increase or  adjustment in pay will be awarded on an individual basis dependent upon your  performance and your overall contribution to the Company's profitability."}),"\n",(0,t.jsx)(o.h2,{id:"job-performance-evaluation",children:"JOB PERFORMANCE EVALUATION"}),"\n",(0,t.jsx)(o.p,{children:"You will be evaluated with respect to the job that you are performing for the Company. As you demonstrate the ability to take on additional responsibilities, your talents will be  utilized in the manner deemed most suitable to your demonstrated ability and the needs of  the Company."}),"\n",(0,t.jsx)(o.p,{children:"A written performance evaluation of each employee will be performed periodically. The evaluation will be conducted by your supervisor and will be reviewed with you. Any  areas of specific achievement or need for improvement will be noted and discussed with you thoroughly."}),"\n",(0,t.jsx)(o.h2,{id:"advancement-and-promotion",children:"ADVANCEMENT AND PROMOTION"}),"\n",(0,t.jsx)(o.p,{children:"The Company's goal is to promote employees from within the current workforce  whenever possible. Once a vacancy is established, you may be promoted provided you  are qualified for such advancement."}),"\n",(0,t.jsx)(o.p,{children:"In making advancement to a new position, the demonstrated ability and overall  qualifications of the applicant will be considered. The final decision on applicants will be  based upon the overall qualification of the applicant and the recommendation of the  applicant's department manager."}),"\n",(0,t.jsx)(o.p,{children:"In certain situations, an opening will occur that requires specialized skills and/or talents  which do not currently exist within the Company. In such cases, the Company will utilize  someone from outside the present work force."}),"\n",(0,t.jsx)(o.h2,{id:"employment-of-relatives",children:"EMPLOYMENT OF RELATIVES"}),"\n",(0,t.jsx)(o.p,{children:'The Company permits the employment of qualified relatives of employees as long as such  employment does not, in the opinion of the Company, create actual or perceived conflicts  of interest. For purposes of this policy, "relative" is defined as a spouse, child, parent,  sibling, grandparent, grandchild, aunt, uncle, first cousin, or corresponding in-law or  "step" relation. The Company will exercise sound business judgment in the placement of  related employees in accordance with the following guidelines:'}),"\n",(0,t.jsxs)(o.ul,{children:["\n",(0,t.jsx)(o.li,{children:'Individuals who are related by blood or marriage are permitted to work in the same  Company facility, provided no direct reporting or supervisory/management  relationship exists. That is, no employee is permitted to work within the "chain of  command" of a relative such that one relative\'s work responsibilities, salary, or  career progress could be influenced by the other relative.'}),"\n",(0,t.jsx)(o.li,{children:"No relatives are permitted to work in the same department or in any other positions  in which the Company believes an inherent conflict of interest may exist.\nThis policy applies to all categories of employment at the Company, including regular,  temporary and part-time classifications."}),"\n"]}),"\n",(0,t.jsx)(o.h2,{id:"non-fraternization",children:"NON-FRATERNIZATION"}),"\n",(0,t.jsx)(o.p,{children:"The Company desires to avoid misunderstandings, actual or potential conflicts of interest,  complaints of favoritism, possible claims of sexual harassment, and the employee morale  and dissension problems that can potentially result from romantic relationships involving  managerial and supervisory employees in the Company or certain other employees in the  Company.\nAccordingly, managers and supervisors are prohibited from fraternizing or becoming  romantically involved with one another or with any other employee of the Company.  Additionally, all employees, both managerial and non-managerial, are prohibited from  fraternizing or becoming romantically involved with other employees, when, in the  opinion of the Company, their personal relationships may create a conflict of interest,  cause disruption, create a negative or unprofessional work environment, or present  concerns regarding supervision, safety, security, or morale."}),"\n",(0,t.jsx)(o.p,{children:"An employee involved with a supervisor or fellow employee should immediately and  fully disclose the relevant circumstances to their supervisor so that a determination can be  made as to whether the relationship violates this policy. If a violation is found, the  Company may take whatever action appears appropriate according to the circumstances,  up to and including transfer or discharge. Failure to disclose facts may lead to  disciplinary action, up to and including termination."}),"\n",(0,t.jsx)(o.p,{children:"All employees should also remember that the Company maintains a strict policy against  unlawful harassment of any kind, including sexual harassment. The Company will  vigorously enforce this policy consistent with all applicable federal, state, and local laws."}),"\n",(0,t.jsx)(o.h2,{id:"appearance",children:"APPEARANCE"}),"\n",(0,t.jsx)(o.p,{children:"All employees are required to report for work in clean clothing and footwear. All  personnel should maintain good grooming and personal hygiene. Clothing which is not  acceptable are items that are sloppy or unkempt, halter tops, shorts, bathing suits, tank tops or T-shirts. We maintain a business casual dress environment and dress accordingly  for client visits."}),"\n",(0,t.jsx)(o.h2,{id:"personal-phone-calls-and-personal-business",children:"PERSONAL PHONE CALLS AND PERSONAL BUSINESS"}),"\n",(0,t.jsx)(o.p,{children:"During business hours, you are requested to keep personal calls to an absolute minimum.  If it is absolutely necessary that you need to make a personal International toll call from  work, you must charge it to your personal calling card or home number or use your  person cell phone. Telephone records are subject to periodic review by management  staff.\nIf you need to leave PPS Facilities during normal work hours to conduct personal  business, you must first obtain permission from your immediate supervisor. This will  allow him to make modifications to the work schedule if necessary and will keep him  aware of your activities during the day."}),"\n",(0,t.jsx)(o.h2,{id:"use-of-communication-systems",children:"USE OF COMMUNICATION SYSTEMS"}),"\n",(0,t.jsx)(o.p,{children:"It is the intent of the Company to provide the communication systems necessary for the  conduct of its business. Employees are expected to adhere to proper use of all  communication systems. These include but are not limited to the Telephone, Electronic  Mail (E-Mail), Facsimile, Internet, Corporate Intranet, Voice Mail, Computer Terminals,  Modems and Systems Software. Employees are permitted use of Company property and  must comply with Company policies and procedures regarding its use.\nThe communication systems are owned and operated by the Company and are to be used  for the business of the Company. Employees should have no expectation of privacy of  any correspondence, messages or information in the systems."}),"\n",(0,t.jsx)(o.p,{children:"The Company reserves the right to access and disclose all such messages sent for any  purpose. All such messages, regardless of content or the intent of the sender, are a form  of corporate correspondence, and are subject to the same internal and external regulation,  security and scrutiny as any other corporate correspondence. E-mail communications  must be written following customary business communications practices as is used in  Company correspondence. E-mail communications are official internal Company  communications, which may be subject to summons in legal proceedings. Work-related  messages should be directed to the affected employee(s) rather than sending a global  message to all employees."}),"\n",(0,t.jsx)(o.p,{children:"The Company\u2019s communication systems shall not be used as a forum to promote religious  or political causes, or an illegal activity. Offensive or improper messages or opinions;  transmission of sexually explicit images, messages, cartoons, or other such items; or  messages that may be construed as harassment or disparagement of others based on race,  national origin, sex, sexual orientation, age, disability, or religion or status as a Vietnam era veteran are also prohibited on the Company\u2019s communication systems."}),"\n",(0,t.jsx)(o.p,{children:"Employees shall not attempt to gain access to another employee\u2019s personal  communications system and messages. The Company, however, reserves the right to  access an employee\u2019s messages at any time, without notice to the employee."}),"\n",(0,t.jsx)(o.p,{children:"Any violation of these guidelines may result in disciplinary action, up to and including  termination."}),"\n",(0,t.jsx)(o.h2,{id:"internet-use",children:"Internet Use"}),"\n",(0,t.jsx)(o.p,{children:"Internet use, on Company time, is authorized to conduct Company business only. Internet  use brings the possibility of breaches to the security of confidential Company  information. Internet use also creates the possibility of contamination to our system via  viruses or spyware. Spyware allows unauthorized people, outside the Company, potential  access to Company passwords and other confidential information."}),"\n",(0,t.jsx)(o.p,{children:"Removing viruses and spyware programs from the Company network requires IT staff to  invest time and attention that is not productive."}),"\n",(0,t.jsx)(o.p,{children:"Additionally, under no circumstances may Company computers or other electronic  equipment be used to obtain, view, or reach any pornographic, or otherwise immoral, unethical, or non-business-related Internet sites. Doing so can lead to disciplinary action including termination."}),"\n",(0,t.jsx)(o.h2,{id:"email-usage",children:"Email Usage"}),"\n",(0,t.jsx)(o.p,{children:"Email is also to be used for Company business only. Company confidential information  must not be shared outside of the Company, without authorization, at any time. You are  also not to conduct personal business using the Company computer or email."}),"\n",(0,t.jsx)(o.p,{children:"Please keep this in mind, also, as you consider forwarding non-business emails to  associates, family or friends. Non-business related emails waste company time and  attention.\nCompany owns any communication sent via email or that is stored on company  equipment. Management and other authorized staff have the right to access any material  in your email or on your computer at any time. Please do not consider your electronic  communication, storage or access to be private if it is created or stored at work."}),"\n",(0,t.jsx)(o.h3,{id:"memory-stick-usb-key",children:"Memory Stick (USB Key)"}),"\n",(0,t.jsx)(o.p,{children:"Memory Sticks also know as USB Keys are only allowed for employees that have a direct  need for their use in the day to day need of their job. No Personal Memory Sticks are  allowed from home and all Memory Sticks should always be scanned for Viruses and  Worms. Talk with your supervisor and consult with the IT department if you have a need  for a Memory Stick."}),"\n",(0,t.jsx)(o.h2,{id:"proprietary-and-confidential-information",children:"PROPRIETARY AND CONFIDENTIAL INFORMATION"}),"\n",(0,t.jsx)(o.p,{children:"It is the guideline of the Company that the general internal business affairs of the  organization and technical know-how and trade secrets should not be discussed with  anyone outside the organization except as may be required in the normal course of  business. Information designated as confidential or proprietary is to be discussed with no  one outside the organization and only discussed within the organization on a need-to know basis. Employees authorized access to confidential information are responsible for  its security."}),"\n",(0,t.jsx)(o.h2,{id:"company-property",children:"COMPANY PROPERTY"}),"\n",(0,t.jsx)(o.p,{children:"In an effort to ensure the safety and welfare of employees and invitees, the Company  reserves the right, on reasonable suspicion that Company policy is being violated, to  conduct searches or inspections of employees and their desks, personal effects, lockers,  lunch boxes, purses, baggage, and any other property located on Company premises or  work sites, their private vehicles, if parked on Company premises or work sites, and their  quarters, if furnished by the Company. Entry on Company premises or work sites  constitutes consent to searches or inspections."}),"\n",(0,t.jsx)(o.h2,{id:"smoking",children:"SMOKING"}),"\n",(0,t.jsx)(o.p,{children:"In order to maintain a safe and comfortable working environment and to ensure  compliance with applicable laws, smoking in Pressure Profile Systems, Inc. offices and facilities is strictly prohibited. Because Pressure Profile Systems may be subject to criminal and civil penalties for violations of applicable smoking laws, we must insist on strict adherence to this policy. Employees smoking in any non-smoking area may be  subject to disciplinary action, up to and including termination. Please contact the Human Resource Department if you have any questions regarding the smoking policy. Complaints regarding violations of this policy may be filed under the Company's complaint resolution procedure, which is described elsewhere in this section of the  handbook."}),"\n",(0,t.jsx)(o.h2,{id:"layoff-due-to-lack-of-work",children:"LAYOFF DUE TO LACK OF WORK"}),"\n",(0,t.jsx)(o.p,{children:"The Company attempts to maintain a stable work force, however, business conditions  sometimes change to a point that there is not enough work to keep all employees on the  payroll. Should such a situation occur, the work force may be reduced by laying off the  number of employees over and above those needed to perform the work available.  Layoffs will be determined by the ability of the affected employees to adequately perform  the available work with a minimum of retraining. Length of service and non-medically  related attendance or tardiness records will be considered where relative ability is equal."}),"\n",(0,t.jsx)(o.h2,{id:"travel",children:"TRAVEL"}),"\n",(0,t.jsx)(o.p,{children:"The Company reimburses employees for the expenses of travel, including the cost of  transportation, meals, lodging, and compensation when appropriate, provided such travel  is approved and performed in the course of conducting Company business."}),"\n",(0,t.jsx)(o.p,{children:"Activities which normally justify the reimbursement of travel expenses include calling on  customers, prospects, and suppliers and the attendance at business meetings, conventions,  and seminars or other selected educational functions related to the employee\u2019s job."}),"\n",(0,t.jsx)(o.p,{children:"Common carrier transportation will be utilized for trips, provided suitable scheduling is  available. Employees are expected to exercise prudence in their selection of local  transportation to their destination. When practical, employees are expected to use a  Company car or personal car for short distance travel."}),"\n",(0,t.jsx)(o.p,{children:"All employees normally are expected to travel coach or economy class and to stay and eat  in moderately priced establishments while traveling on Company business."}),"\n",(0,t.jsx)(o.p,{children:"Non-exempt employees will be compensated for *time spent traveling if that travel is part  of the employee\u2019s daily work activity, including travel from one job site to another or  travel from a designated meeting place to a job site. Travel by a non-exempt employee  who will be away from home overnight is work time only during those periods the  employee is engaged in Company business, which typically will coincide with the  employee\u2019s regular working hours. Such time counts as hours worked even if it occurs on a non-working day. If an employee uses his or her own car rather than available public  transportation for travel away from home, the employee can count as hours worked either  the time spent driving or the time that would have been spent on public transportation  during regular working hours."}),"\n",(0,t.jsx)(o.p,{children:"*International and Domestic Travel time is compensated at 8 hours per day (straight time)."})]})}function h(e={}){const{wrapper:o}={...(0,a.R)(),...e.components};return o?(0,t.jsx)(o,{...e,children:(0,t.jsx)(c,{...e})}):c(e)}},8453(e,o,n){n.d(o,{R:()=>s,x:()=>r});var i=n(6540);const t={},a=i.createContext(t);function s(e){const o=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(o):{...o,...e}},[o,e])}function r(e){let o;return o=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:s(e.components),i.createElement(a.Provider,{value:o},e.children)}}}]);